  "check_code": "#!/usr/bin/env python3
"""Deterministic post-state checks for the remediation workbook."""

from datetime import date, datetime
from pathlib import Path

from openpyxl import load_workbook


WORKBOOK = Path("03_Findings_and_Response/Adobe_ETH-2025-0917_Discipline_and_Control_Remediation.xlsx")
TARGET_ID = "CR-002"

OTHER_CONTROL_STATES = {
    "CR-001": ("Complete", "Pass", "Not tested", "Not tested"),
    "CR-003": ("In progress", "Partial", "Not tested", "Not tested"),
    "CR-004": ("Delayed", "Fail", "Not tested", "Not tested"),
    "CR-005": ("Not started", "Not tested", "Not tested", "Not tested"),
    "CR-006": ("Complete", "Pass", "Not tested", "Not tested"),
    "CR-007": ("In progress", "Partial", "Not tested", "Not tested"),
    "CR-008": ("Not started", "Not tested", "Not tested", "Not tested"),
    **{
        f"CR-RES-{number:02d}": ("Complete", "Not tested", "Not tested", "Not tested")
        for number in range(1, 12)
    },
}


def _result(score, detail):
    return {"score": score, "detail": detail}


def _path(ws):
    return Path(ws) / WORKBOOK


def _rows(sheet):
    return list(sheet.iter_rows(values_only=True))


def _find_control_row(sheet, control_id):
    wanted = norm_label(control_id)
    for row in _rows(sheet):
        if row and norm_label(row[0]) == wanted:
            return row
    raise KeyError(f"Control Remediation has no row for {control_id}")


def _as_date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    return datetime.fromisoformat(str(value).strip()).date()


def check_implementation_status(ws):
    try:
        sheet = load_sheet(_path(ws), "Control Remediation")
        row = _find_control_row(sheet, TARGET_ID)
        actual = row[8]
        passed = norm_label(actual) == norm_label("Complete")
        return _result(1 if passed else 0, f"CR-002 implementation status={actual!r}")
    except Exception as exc:
        return _result(0, f"implementation-status check failed: {exc}")


def check_thirty_day_result(ws):
    try:
        sheet = load_sheet(_path(ws), "Control Remediation")
        row = _find_control_row(sheet, TARGET_ID)
        actual = row[10]
        passed = norm_label(actual) == norm_label("Pass")
        return _result(1 if passed else 0, f"CR-002 30-day result={actual!r}")
    except Exception as exc:
        return _result(0, f"30-day-result check failed: {exc}")


def check_target_row_preserved(ws):
    try:
        path = _path(ws)
        calculated = load_sheet(path, "Control Remediation")
        row = _find_control_row(calculated, TARGET_ID)
        value_checks = [
            _as_date(row[6]) == date(2025, 11, 7),
            norm_label(row[11]) == norm_label("Not tested"),
            norm_label(row[12]) == norm_label("Not tested"),
        ]

        formula_book = load_workbook(path, data_only=False, read_only=True)
        formula_sheet = formula_book["Control Remediation"]
        formula_cell = None
        for excel_row in formula_sheet.iter_rows():
            if excel_row and norm_label(excel_row[0].value) == norm_label(TARGET_ID):
                formula_cell = excel_row[9]
                break
        formula_ok = formula_cell is not None and formula_cell.data_type == "f"
        checks = value_checks + [formula_ok]
        return _result(1 if all(checks) else 0, f"CR-002 preservation checks {sum(checks)}/{len(checks)}")
    except Exception as exc:
        return _result(0, f"target-row preservation check failed: {exc}")


def check_unrelated_controls_preserved(ws):
    try:
        remediation = load_sheet(_path(ws), "Control Remediation")
        actual_states = {}
        for row in _rows(remediation):
            if row and norm_label(row[0]) in {norm_label(key) for key in OTHER_CONTROL_STATES}:
                actual_states[str(row[0]).strip().upper()] = (row[8], row[10], row[11], row[12])

        state_checks = []
        for control_id, expected in OTHER_CONTROL_STATES.items():
            actual = actual_states.get(control_id)
            state_checks.append(
                actual is not None
                and all(norm_label(left) == norm_label(right) for left, right in zip(actual, expected))
            )

        validation = load_sheet(_path(ws), "Validation 30-60-90")
        validation_results = {}
        for row in _rows(validation):
            if len(row) >= 8 and "cr-002" in norm_label(row[6]):
                validation_results[norm_label(row[2])] = row[7]
        schedule_ok = (
            norm_label(validation_results.get("30-day")) == norm_label("Partial")
            and norm_label(validation_results.get("60-day")) == norm_label("Not tested")
            and norm_label(validation_results.get("90-day")) == norm_label("Not tested")
        )
        checks = state_checks + [schedule_ok]
        return _result(1 if all(checks) else 0, f"unrelated control/schedule checks {sum(checks)}/{len(checks)}")
    except Exception as exc:
        return _result(0, f"unrelated-controls preservation check failed: {exc}")
